-- "user" is just a role WITH LOGIN
CREATE ROLE app_user WITH LOGIN PASSWORD 'secret';

-- a "role" is a role withOUT login,
-- used purely for permission grouping
CREATE ROLE reporting_team;

-- CREATE USER is shorthand for the first form

CREATE ROLE ops_admin WITH LOGIN
  PASSWORD 'another_secret'
  CREATEDB CREATEROLE;

GRANT reporting_team TO app_user;
